def anthropic_tools() -> list[dict]:
    """Convert the shared tool schemas to Anthropic's tool format.

    ``TOOLS`` stays in OpenAI/realtime shape because the Grok speech-to-speech
    transport consumes it directly; Claude needs ``input_schema`` instead.
    """
    return [
        {
            "name": tool["function"]["name"],
            "description": tool["function"]["description"],
            "input_schema": tool["function"]["parameters"],
        }
        for tool in TOOLS
        if tool["function"]["name"] in {"search_trusted_web", "show_visualization"}
    ]


# --------------------------------------------------------------------------
# Tool implementations.
# --------------------------------------------------------------------------


def _json(data: dict) -> str:
    return json.dumps(data, ensure_ascii=False)


def _tool_log_value(value: object, limit: int = 600) -> str:
    """Return compact, bounded JSON for tool debugging logs."""
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except json.JSONDecodeError:
            pass
    text = json.dumps(value, ensure_ascii=False, default=str, separators=(",", ":"))
    return text if len(text) <= limit else f"{text[:limit]}…"


def show_visualization(**args) -> str:
    """Validate one formula, flow diagram, or numeric plot for the chat UI.

    Args:
        **args: Structured visualization fields from the model tool call.

    Returns:
        JSON string containing only validated, render-safe data.
    """
    visualization = Visualization(**_normalize_visualization_args(args))
    if visualization.kind == "formula" and not re.search(r"[^\W_]", visualization.latex):
        raise ValueError("formula visualization requires meaningful latex")
    if visualization.kind == "flow" and len(visualization.labels) < 2:
        raise ValueError("flow visualization requires at least two labels")
    if visualization.kind == "plot" and len(visualization.points) < 2:
        raise ValueError("plot visualization requires at least two points")
    if visualization.kind == "pdf" and (not visualization.file.strip() or visualization.page < 1):
        raise ValueError("pdf visualization requires an exact file and page")
    return _json(visualization.model_dump())


def _normalize_visualization_args(args: dict) -> dict:
    """Accept harmless provider variations before applying strict validation."""
    normalized = dict(args)
    nested = normalized.pop("visualization", None)
    if isinstance(nested, dict):
        normalized = {**nested, **normalized}

    aliases = {
        "type": "kind",
        "name": "title",
        "description": "caption",
        "equation": "latex",
        "formula": "latex",
    }
    for source, target in aliases.items():
        if target not in normalized and source in normalized:
            normalized[target] = normalized[source]

    latex = normalized.get("latex")
    if isinstance(latex, str):
        latex = latex.strip()
        if len(latex) > 4 and latex.startswith("$$") and latex.endswith("$$"):
            latex = latex[2:-2].strip()
        elif len(latex) > 2 and latex.startswith("$") and latex.endswith("$"):
            latex = latex[1:-1].strip()
        normalized["latex"] = latex

    if "labels" not in normalized:
        for key in ("nodes", "steps", "items"):
            if key in normalized:
                normalized["labels"] = normalized[key]
                break
    labels = normalized.get("labels")
    if isinstance(labels, str):
        normalized["labels"] = [
            value.strip()
            for value in re.split(r"\s*(?:→|->|=>|\||,|\n)\s*", labels)
            if value.strip()
        ]
    return normalized


def _terms(text: str) -> set[str]:
    return {
        token.casefold()
        for token in re.findall(r"[0-9A-Za-z가-힣_]{2,}", text)
        if token.casefold() not in {"대해서", "설명", "질문", "무엇", "어떻게"}
    }


def search_course_materials(course_id: str, query: str) -> tuple[str, list[dict]]:
    """Search the course knowledge base through the shared RAG service.

    Args:
        course_id: Course whose processed materials may be searched.
        query: Focused terms from the student question.

    Returns:
        Tuple of the JSON tool result and the structured citations for logging.
    """
    # Imported here so the voice package stays importable without a database.
    from app.core.config import get_settings
    from app.db.session import SessionLocal
    from app.services.rag_service import RagService

    query = (query or "").strip()
    if not _terms(query):
        return _json({"error": "a focused course-material search query is required"}), []

    with SessionLocal() as session:
        outcome = RagService(session, get_settings()).retrieve(course_id, query, PDF_MAX_RESULTS)

    citations = [
        {
            "material_id": result.material_id,
            "document_name": result.document_name,
            "page_number": result.page_number,
            "chunk_index": result.chunk_index,
            "score": round(result.score, 4),
        }
        for result in outcome.results
    ]
    results = [
        {
            "source": _source_label(result.document_name, result.page_number),
            "file": result.document_name,
            "page": result.page_number or 0,
            "material_id": result.material_id,
            "excerpt": result.chunk_text.strip()[:1000],
        }
        for result in outcome.results
    ]
    payload = {
        "found": bool(results),
        "query": query,
        "results": results,
        "instruction": (
            "Use the document name and page in the answer."
            if results
            else "No course-material evidence found; trusted web search is now allowed."
        ),
    }
    if not results and outcome.summary.reason:
        payload["reason"] = outcome.summary.reason
    return _json(payload), citations


def _source_label(document_name: str, page_number: Optional[int]) -> str:
    return f"{document_name} p.{page_number}" if page_number else document_name


def _compact_memory(memory: dict) -> dict:
    compact = {
        "concept": memory.get("concept", ""),
        "difficulty": memory.get("difficulty_note") or memory.get("difficulty", ""),
        "status": memory.get("status", "new"),
    }
    if memory.get("course"):
        compact["course"] = memory["course"]
    return compact


async def recent_weak_concepts(context: VoiceContext, *, top_k: int = MEMORY_TOP_K) -> dict:
    """Return the learner's most recent compact weak-concept records."""
    memories = await context.memory.all_memories()
    if not isinstance(memories, list):
        return {"found": False, "memories": []}
    memories.sort(
        key=lambda item: (
            float(item.get("last_seen_at", 0) or 0),
            float(item.get("saved_at", 0) or 0),
        ),
        reverse=True,
    )
    compact = [_compact_memory(item) for item in memories[:top_k]]
    compact = [item for item in compact if item["concept"]]
    return {"found": bool(compact), "memories": compact}


async def prefetch_memory_context(context: VoiceContext, question: str = "") -> dict:
    """Prefetch only learner memory for a realtime voice session."""
    try:
        memory = await recent_weak_concepts(context)
    except Exception as exc:
        memory = {"error": f"memory prefetch failed: {exc}"}
    return {"student_question": question.strip(), "weak_concepts": memory}


def retrieval_query(context: VoiceContext, question: str) -> str:
    """Give short student answers the question they are answering for retrieval."""
    previous = context.history[:-1] if (
        context.history and context.history[-1] == {"role": "user", "content": question}
    ) else context.history
    if not previous or len(question) > 80:
        return question
    referential = re.search(r"^(그럼|그게|그건|그거|이거|저거|이 식|저 식|그 식|왜|어떻게)", question)
    new_question = re.search(r"뭐|무엇|알려|설명|정의|차이|새로운|다른 주제|대해|\?", question)
    if new_question and not referential:
        return question
    # ponytail: short-answer heuristic; use a query rewriter if dialogue evals expose gaps.
    turns = [str(item.get("content", "")) for item in previous[-2:]]
    visual_titles = [str(item.get("title", "")) for item in context.last_visualizations]
    return "\n".join([*turns, *visual_titles, question])[-1600:]


async def prefetch_context(
    context: VoiceContext,
    question: str,
    timer: StageTimer | None = None,
) -> dict:
    """Prefetch learner memory and course evidence in parallel for text chat."""

    async def recall() -> dict:
        started = time.perf_counter()
        try:
            try:
                return await recent_weak_concepts(context)
            except Exception as exc:
                log.warning("learner-memory prefetch failed: %s", exc)
                return {"found": False, "memories": []}
        finally:
            if timer is not None:
                timer.record("recall", started)

    async def retrieve() -> tuple[str, list[dict]]:
        started = time.perf_counter()
        try:
            try:
                return await asyncio.to_thread(
                    search_course_materials, context.course_id, retrieval_query(context, question)
                )
            except Exception as exc:
                log.warning("course-material prefetch failed: %s", exc)
                return _json({"found": False, "error": str(exc)}), []
        finally:
            if timer is not None:
                timer.record("material", started)

    memory, (raw_materials, citations) = await asyncio.gather(recall(), retrieve())
    context.last_material_sources = citations
    try:
        materials = json.loads(raw_materials)
    except json.JSONDecodeError:
        materials = {"error": "course material prefetch returned invalid JSON"}
    return {
        "student_question": question.strip(),
        "weak_concepts": memory,
        "course_materials": materials,
    }


def answer_instructions(context: VoiceContext, mode: str, prefetched: dict) -> str:
    """Build the latest KINGO text policy with server-prefetched context."""
    payload = json.dumps(
        {**prefetched, "recent_visualizations": context.last_visualizations},
        ensure_ascii=False, separators=(",", ":"),
    )
    return "\n\n".join(
        (
            SYSTEM_PROMPT,
            f"# Course\nThis session belongs to '{context.course_name}'.",
            SOCRATIC_PROMPT,
            "# Preloaded context\n"
            f"{payload}",
        )
    )


WEB_SEARCH_SYSTEM_PROMPT = (
    "Answer in Korean using only the web-search evidence. "
    "Keep source URLs in the tool result, not in the prose answer. "
    "If evidence is insufficient, say so."
)


async def search_trusted_web(
    course_id: str,
    query: str,
    pdf_evidence_insufficient: bool = False,
    reason: str = "",
) -> str:
    """Search the course allowlist through Claude and retain citation audit data.

    Args:
        course_id: Course whose professor-managed allowlist applies.
        query: Focused external search query.
        pdf_evidence_insufficient: Whether course material evidence is insufficient.
        reason: Evidence gap permitting web fallback.

    Returns:
        JSON string with cited answer and trusted source URLs.
    """
    query = (query or "").strip()
    reason = (reason or "").strip()
    if not query:
        return _json({"error": "web search query is required"})
    if not reason:
        return _json({"error": "course-material fallback reason is required"})

    try:
        found = await LLMService(get_settings()).search_web(
            query=query,
            system=WEB_SEARCH_SYSTEM_PROMPT,
            allowed_domains=get_trusted_domains(course_id),
        )
    except LLMError as exc:
        return _json({"error": str(exc), "query": query})

    answer, sources = found.answer, found.sources
    if not answer or not sources:
        return _json(
            {
                "error": "trusted web search returned no citable sources",
                "query": query,
            }
        )

    record = {
        "course_id": course_id,
        "query": query,
        "answer": answer,
        "sources": sources,
        "pdf_evidence_insufficient": pdf_evidence_insufficient,
        "fallback_reason": reason,
        "searched_at": time.time(),
    }
    log_path = voice_storage_dir() / "web-search.jsonl"
    with log_path.open("a", encoding="utf-8") as file:
        file.write(_json(record) + "\n")
    return _json(
        {
            "found": True,
            "answer": answer,
            "sources": sources,
            "instruction": "The UI displays source URLs separately; do not repeat them in the answer.",
        }
    )


async def run_tool(context: VoiceContext, name: str, args: dict, timer: StageTimer) -> str:
    """Dispatch one validated function tool call.

    Args:
        context: Course-scoped session state.
        name: Tool name emitted by Grok.
        args: Parsed JSON arguments matching the tool schema.
        timer: Collector receiving tool latency.

    Returns:
        JSON string containing tool output or a recoverable error.
    """
    started_at = time.perf_counter()
    stage = {
        "recall_weak_concepts": "recall",
        "search_course_materials": "material",
        "search_trusted_web": "web",
        "save_weak_concept": "save",
        "review_weak_concept": "review",
        "show_visualization": "visual",
    }.get(name, "tool")
    log.info("tool call name=%s args=%s", name, _tool_log_value(args))
    try:
        if not isinstance(args, dict):
            raise TypeError("tool arguments must be an object")
        if name == "recall_weak_concepts":
            result = _json(await context.memory.recall(**args))
        elif name == "search_course_materials":
            result, citations = await asyncio.to_thread(
                search_course_materials, context.course_id, **args
            )
            if citations:
                context.last_material_sources = citations
        elif name == "search_trusted_web":
            result = await search_trusted_web(
                context.course_id,
                pdf_evidence_insufficient=True,
                **args,
            )
        elif name == "save_weak_concept":
            result = _json(await context.memory.save(**args))
        elif name == "review_weak_concept":
            result = _json(await context.memory.review(**args))
        elif name == "show_visualization":
            result = show_visualization(**args)
        else:
            result = _json({"error": f"unknown tool: {name}"})
    except (TypeError, ValueError) as exc:
        result = _json({"error": f"invalid {name} arguments: {exc}"})
    except Exception as exc:
        log.exception("tool %s failed", name)
        result = _json({"error": str(exc)})
    finally:
        timer.record(stage, started_at)
    payload = json.loads(result)
    status = "error" if isinstance(payload, dict) and "error" in payload else "ok"
    elapsed_ms = round((time.perf_counter() - started_at) * 1000)
    log.info(
        "tool result name=%s status=%s elapsed_ms=%d result=%s",
        name,
        status,
        elapsed_ms,
        _tool_log_value(payload),
    )
    return result


# --------------------------------------------------------------------------
# Function-tool response pipeline.
# --------------------------------------------------------------------------

CONFUSION_MARKERS = (
    "모르겠",
    "모르겠어",
    "잘 모르",
    "어려워",
    "어렵",
    "헷갈",
    "이해가 안",
    "이해 안",
    "이해되지",
    "감이 안",
    "막혀",
    "틀린 것 같",
    "don't know",
    "do not know",
    "confused",
    "difficult",
    "hard to understand",
)


def _explicit_confusion(transcript: str) -> bool:
    normalized = transcript.casefold()
    return any(marker in normalized for marker in CONFUSION_MARKERS)


def _fallback_weak_concept(course_name: str, transcript: str) -> WeakConceptCapture:
    concise_question = re.sub(r"\s+", " ", transcript).strip()
    return WeakConceptCapture(
        course=course_name or "미지정 과목",
        concept=concise_question[:160],
        original_question=concise_question,
        difficulty_note="학생이 명시적으로 이해 부족, 혼란 또는 어려움을 표현함",
    )


def _conversation(history: list[dict]) -> list[dict]:
    """Return the history trimmed to something Claude accepts.

    A conversation must start with a user message; a pending review prompt can
    leave an assistant message first, so drop any leading assistant turns.
    """
    start = 0
    while start < len(history) and history[start].get("role") != "user":
        start += 1
    return history[start:]


async def think(
    context: VoiceContext,
    transcript: str,
    timer: StageTimer,
    mode: str = "socratic",
    on_token: Callable[[str], Awaitable[None]] | None = None,
) -> tuple[str, list[str], list[str], list[dict]]:
    """Generate one grounded Socratic response through Claude's tool use.

    Args:
        context: Course-scoped session state.
        transcript: Student utterance transcribed to text.
        timer: Collector for tool and model latency.
        mode: Legacy request field; teaching is always Socratic.
        on_token: Optional callback receiving streamed answer tokens.

    Returns:
        Reply text, tool names, trusted source URLs, and visual references.
    """
    context.append_history({"role": "user", "content": transcript})
    context.last_material_sources = []
    llm = LLMService(get_settings())
    tool_messages: list[dict] = []
    tools_used: list[str] = []
    external_sources: list[str] = []
    visualizations: list[dict] = []
    prefetched = await prefetch_context(context, transcript, timer)
    system = answer_instructions(context, mode, prefetched)
    tools = anthropic_tools()

    for _ in range(MAX_TOOL_ROUNDS):
        started_at = time.perf_counter()
        turn = await llm.stream_tool_turn(
            system=system,
            messages=[*_conversation(context.history), *tool_messages],
            tools=tools,
            on_token=on_token,
        )
        elapsed_ms = round((time.perf_counter() - started_at) * 1000)
        timer.timings_ms["llm"] = timer.timings_ms.get("llm", 0) + elapsed_ms
        log.info("stage llm   %5d ms (%s)", elapsed_ms, turn.model_name)

        if not turn.tool_calls:
            reply_text = turn.text.strip() or "답변을 생성하지 못했어요. 다시 질문해 주세요."
            if external_sources:
                reply_text = for_speech(reply_text)

            context.append_history({"role": "assistant", "content": reply_text})
            if visualizations:
                context.last_visualizations = visualizations[-3:]
            from app.services.voice.session_store import external_brain_for

            external_brain_for(
                context.user_id,
                context.course_id,
                context.course_name,
            ).schedule(context.history, source="text")
            return reply_text, tools_used, external_sources[:3], visualizations

        assistant_blocks: list[dict] = []
        if turn.text.strip():
            assistant_blocks.append({"type": "text", "text": turn.text})
        assistant_blocks.extend(
            {"type": "tool_use", "id": call.id, "name": call.name, "input": call.arguments}
            for call in turn.tool_calls
        )
        tool_messages.append({"role": "assistant", "content": assistant_blocks})

        results = await asyncio.gather(
            *(run_tool(context, call.name, call.arguments, timer) for call in turn.tool_calls)
        )
        result_blocks: list[dict] = []
        for call, result in zip(turn.tool_calls, results):
            if call.name not in tools_used:
                tools_used.append(call.name)
            if call.name == "search_trusted_web":
                external_sources = json.loads(result).get("sources", [])
            elif call.name == "show_visualization":
                visual = json.loads(result)
                if "error" not in visual:
                    visualizations.append(visual)
            result_blocks.append({"type": "tool_result", "tool_use_id": call.id, "content": result})
        tool_messages.append({"role": "user", "content": result_blocks})

    raise RuntimeError("the assistant exceeded the tool-call round limit")


# --------------------------------------------------------------------------
# Speech and lifecycle helpers.
# --------------------------------------------------------------------------


# Latin letters read out one at a time, in Korean. The TTS model mispronounces
# upper-case acronyms and can emit a tonal artefact on them, and unlike prose the
# correct reading is fully determined, so spell them for speech only.
_LETTER_HANGUL = {
    "A": "에이", "B": "비", "C": "씨", "D": "디", "E": "이", "F": "에프",
    "G": "지", "H": "에이치", "I": "아이", "J": "제이", "K": "케이", "L": "엘",
    "M": "엠", "N": "엔", "O": "오", "P": "피", "Q": "큐", "R": "알",
    "S": "에스", "T": "티", "U": "유", "V": "브이", "W": "더블유", "X": "엑스",
    "Y": "와이", "Z": "제트",
}
# Acronyms conventionally read as a word rather than letter by letter. Anything
# not listed here falls through to the letter table, which is already correct for
# the likes of HTTP or SQL.
_SPOKEN_AS_WORD = {"RAM": "램", "ROM": "롬", "JSON": "제이슨", "REST": "레스트"}
# LLM-authored pronunciation hints stay visible on screen, while TTS reads only
# their Hangul side so mixed-language terms do not inherit Korean-mode English.
_PRONUNCIATION = re.compile(
    r"(?<![A-Za-z])(?:[A-Za-z][A-Za-z0-9+.#/-]*(?: +[A-Za-z][A-Za-z0-9+.#/-]*)*)"
    r"\(([가-힣]+(?: +[가-힣]+)*)\)"
)
# Korean particles attach directly to acronyms, so bound on Latin characters.
_ACRONYM = re.compile(r"(?<![A-Za-z0-9])[A-Z][A-Z0-9]{1,5}(?![A-Za-z0-9])")
# Written with a slash, so the acronym pattern cannot reach it.
_SLASHED = {"I/O": "아이오"}


def _spell_acronym(match: re.Match[str]) -> str:
    token = match.group(0)
    if token in _SPOKEN_AS_WORD:
        return _SPOKEN_AS_WORD[token]
    if not any(character.isalpha() for character in token):
        return token
    return "".join(_LETTER_HANGUL.get(character, character) for character in token)


def for_speech(text: str) -> str:
    """Adapt screen text for the TTS model without changing what is displayed.

    URLs are dropped, pronunciation hints select their Hangul reading, and acronyms
    are spelled out in Hangul. Original spelling stays intact on screen.
    """
    text = re.sub(
        r"\s*외부 출처\s*:?\s*(?:https?://\S+\s*,?\s*)+$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"https?://\S+", "", text)
    text = _PRONUNCIATION.sub(r"\1", text)
    for written, spoken in _SLASHED.items():
        text = text.replace(written, spoken)
    return _ACRONYM.sub(_spell_acronym, text).strip()


# Kept under the original private name so ported tests keep passing.
_for_speech = for_speech


async def next_review_prompt(context: VoiceContext) -> dict:
    """Return the next due weak concept for this learner, if any."""
    memory = await context.memory.next_review()
    if memory is None:
        return {"due": False}
    question = f"{memory['concept']}을 자신의 말로 설명해 볼까요?"
    context.append_history(
        {
            "role": "assistant",
            "content": f"복습 질문 (memory_id={memory['id']}): {question}",
        }
    )
    return {
        "due": True,
        "memory_id": memory["id"],
        "concept": memory["concept"],
        "question": question,
    }


async def list_weak_concepts(context: VoiceContext) -> list[dict]:
    """Return this learner's weak concepts for the current authorized course."""
    memories = await context.memory.all_memories()
    course_memories = [
        memory for memory in memories if memory.get("course") == context.course_name
    ]
    return [
        {
            "memory_id": memory.get("id", ""),
            "concept": memory.get("concept", ""),
            "difficulty_note": memory.get("difficulty_note", ""),
            "status": memory.get("status", "new"),
            "mastery_percent": round(
                min(max(float(memory.get("confidence", 0)), 0), 1) * 100
            ),
            "success_count": int(memory.get("success_count", 0)),
            "failure_count": int(memory.get("failure_count", 0)),
            "last_seen_at": float(memory.get("last_seen_at", 0)),
            "next_review_at": float(memory.get("next_review_at", 0)),
        }
        for memory in sorted(
            course_memories,
            key=lambda item: float(item.get("last_seen_at", 0)),
            reverse=True,
        )
    ]
